const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const alBayda = ee.Geometry.Point([21.7551, 32.7627]).buffer(5000); // 5km buffer around Al Bayda
  const date1 = '2023-09-08';
  const date2 = '2023-09-13';

  // 2. Data Acquisition
  const viirsCol = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
    .filterBounds(alBayda);

  // Get images for specific dates
  const img1 = viirsCol.filterDate(date1, ee.Date(date1).advance(1, 'day')).first();
  const img2 = viirsCol.filterDate(date2, ee.Date(date2).advance(1, 'day')).first();

  // Check if images exist
  const img1Exists = img1 ? true : false;
  const img2Exists = img2 ? true : false;

  if (!img1Exists || !img2Exists) {
    console.log(`Sept 8 image: ${img1Exists ? 'Found' : 'Missing'}`);
    console.log(`Sept 13 image: ${img2Exists ? 'Found' : 'Missing'}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Extract nighttime light values
  const band = 'avg_rad';

  // Get pixel counts and mean values
  const stats1 = img1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: alBayda,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2 = img2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: alBayda,
    scale: 1000,
    maxPixels: 1e9
  });

  const mean1 = stats1.get('mean').getInfo();
  const count1 = stats1.get('count').getInfo();
  const mean2 = stats2.get('mean').getInfo();
  const count2 = stats2.get('count').getInfo();

  console.log(`Sept 8: Mean=${mean1?.toFixed(4)}, Pixels=${count1}`);
  console.log(`Sept 13: Mean=${mean2?.toFixed(4)}, Pixels=${count2}`);

  // 4. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
  } else if (mean1 === null || mean2 === null || isNaN(mean1) || isNaN(mean2)) {
    console.log("<answer>C3</answer>");
  } else if (mean2 < mean1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
